={{ (() => {
  const title = $json.title || '';
  const source = $json.source || '';
  const category = $json.category || '';
  const body = $json.article_body || '';

  const koreanChars = (title.match(/[가-힣]/g) || []).length;
  const isEnglishTitle = koreanChars === 0 && title.trim().length > 3;

  let prompt = '당신은 뉴스 기사를 간결하게 요약하는 전문가입니다.\n\n';
  prompt += '절대 규칙:\n';
  prompt += '- 기사 본문에 나온 내용만 요약할 것. 본문에 없는 정보를 추가하거나 추측하지 말 것\n';
  prompt += '- 인물 이름은 본문에 나온 그대로 사용할 것. 한자 이름을 임의로 해석하지 말 것\n';
  prompt += '- 李대통령, 尹대통령 등 한자 약칭은 본문 맥락에서 확인된 이름만 사용할 것\n\n';

  if (isEnglishTitle) {
    prompt += '이 기사는 영어 기사입니다. 반드시 전체를 한국어로 번역하여 요약하세요.\n';
    prompt += '첫 번째 줄: 📌 제목을 자연스러운 한국어로 번역 (예: 📌 오픈AI, 새 모델 발표)\n';
    prompt += '(빈 줄)\n';
    prompt += '두 번째 줄부터 아래 규칙으로 한국어 요약:\n\n';
  }

  prompt += '요약 형식 규칙:\n';
  prompt += '1. 5~8문장으로 요약할 것 (충분히 상세하게)\n';
  prompt += '2. 각 불릿(•) 문장 사이에 빈 줄을 넣어 가독성을 높일 것\n';
  prompt += '3. 문장 앞에 불릿(•)을 붙일 것\n';
  prompt += '4. 어려운 용어는 괄호 안에 쉬운 설명을 추가할 것\n';
  prompt += '5. 마지막 문장은 시사점 또는 결론으로 마무리\n';
  prompt += '6. 출력은 요약 내용만, 추가 설명이나 사족 없이\n\n';
  prompt += '출력 예시:\n';
  prompt += '• 첫 번째 핵심 내용.\n';
  prompt += '\n';
  prompt += '• 두 번째 핵심 내용.\n';
  prompt += '\n';
  prompt += '• 세 번째 핵심 내용.\n\n';

  prompt += '기사 제목: ' + title + '\n';
  prompt += '출처: ' + source + '\n';
  prompt += '카테고리: ' + category + '\n\n';

  if (body && body.length > 50) {
    prompt += '기사 본문:\n' + body;
  } else {
    prompt += '(본문 없음 - 이 기사는 건너뛰세요. SKIP이라고만 출력하세요.)';
  }

  return {
    model: 'anthropic/claude-haiku-4-5',
    max_tokens: 800,
    messages: [{ role: 'user', content: prompt }]
  };
})() }}

parameters.jsCode:
const resp = $input.item.json;
const summary = resp.choices?.[0]?.message?.content?.trim() || '';
const article = $('배치 분리').item.json;
const title = article.title || '';

// Check if article should be skipped
if (!summary || summary === 'SKIP' || summary.includes('SKIP')) {
  return [];
}

// Check if English title needs translation
const koreanChars = (title.match(/[가-힣]/g) || []).length;
const isEnglish = koreanChars === 0 && title.trim().length > 3;

if (isEnglish && !summary.startsWith('📌')) {
  // 📌 없으면 자동으로 제목 앞에 추가하여 저장
  const translatedSummary = '📌 ' + title + '\n' + summary;
  return [{ json: { id: article.id, summary: translatedSummary } }];
}

return [{ json: { id: article.id, summary: summary } }];

const html = $input.item.json.data || $input.item.json.body || '';
const article = $('배치 분리').item.json;

let text = html
  .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '')
  .replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '')
  .replace(/<nav[^>]*>[\s\S]*?<\/nav>/gi, '')
  .replace(/<header[^>]*>[\s\S]*?<\/header>/gi, '')
  .replace(/<footer[^>]*>[\s\S]*?<\/footer>/gi, '')
  .replace(/<aside[^>]*>[\s\S]*?<\/aside>/gi, '');

// 다양한 HTML 구조에서 본문 추출 시도
let bodyMatch = text.match(/<article[^>]*class=['"][^'"]*story-news[^'"]*['"][^>]*>([\s\S]*?)<\/article>/i);
if (!bodyMatch) bodyMatch = text.match(/<article[^>]*>([\s\S]*?)<\/article>/i);
if (!bodyMatch) bodyMatch = text.match(/class=['"][^'"]*article[_-]?body[^'"]*['"][^>]*>([\s\S]*?)<\/div>/i);
if (!bodyMatch) bodyMatch = text.match(/class=['"][^'"]*post[_-]?content[^'"]*['"][^>]*>([\s\S]*?)<\/div>/i);
if (!bodyMatch) bodyMatch = text.match(/class=['"][^'"]*entry[_-]?content[^'"]*['"][^>]*>([\s\S]*?)<\/div>/i);
if (!bodyMatch) bodyMatch = text.match(/<main[^>]*>([\s\S]*?)<\/main>/i);
if (bodyMatch) text = bodyMatch[1];

text = text.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();

if (text.length > 2000) text = text.substring(0, 2000) + '...';

return [{ json: { ...article, article_body: text.length > 50 ? text : '' } }];
